correct_example.code:
function cancel(bytes32 _proposalId) external {
    Proposal memory proposal = proposals[_proposalId];
    if (msg.sender != proposal.proposer && getVotes(proposal.proposer, block.timestamp - 1) >= proposal.proposalThreshold)
        revert INVALID_CANCEL();
    proposals[_proposalId].canceled = true;
    emit ProposalCanceled(_proposalId);
}

function addMember(address _newMember, Cohort _cohort) external onlyRole(MEMBER_ADDER_ROLE) {
    require(!removedMembers[_newMember], "Member previously removed by governance");
    _addMemberToCohortArray(_newMember, _cohort);
    _scheduleUpdate();
    emit MemberAdded(_newMember, _cohort);
}

function _swapMembers(address _addressToRemove, address _addressToAdd) internal returns (Cohort) {
    require(!electionInProgress, "Cannot swap during election");
    Cohort cohort = _removeMemberFromCohortArray(_addressToRemove);
    _addMemberToCohortArray(_addressToAdd, cohort);
    _scheduleUpdate();
    return cohort;
}

function proposalThreshold() public view returns (uint256) {
    uint256 supply = settings.token.totalSupply();
    uint256 raw = (supply * settings.proposalThresholdBps) / 10_000;
    return raw == 0 ? 1 : raw;
}
